import type { ID } from '@/domain/types';
import { PASSWORD_TOO_SHORT, isPasswordLongEnough } from '@/domain/account';
import { ADMIN_ACTOR, type AppData } from './data';
import { uid } from './orderMutations';
import { fail, ok, type Result } from './result';

export interface PasswordResetTarget {
  role: 'merchant' | 'captain';
  id: ID;
}

/**
 * Admin resets a Merchant's or Captain's password to a one-time temporary password (generated by
 * the composition root, shown to Admin once to hand over). The old password is never read or
 * shown; the audit entry records who, whom and when — never a password.
 *
 * DEMO ONLY: this prototype keeps credentials in the browser. Production must run this on the
 * server (ASP.NET Identity `GeneratePasswordResetTokenAsync` / `ResetPasswordAsync` or an approved
 * admin flow) with RBAC, hashing, rate limiting, session revocation and an audited handoff.
 */
export function resetAccountPassword(d: AppData, now: number, target: PasswordResetTarget, temporaryPassword: string): Result<{ name: string; username: string }> {
  if (!isPasswordLongEnough(temporaryPassword)) return fail(PASSWORD_TOO_SHORT);
  const account =
    target.role === 'merchant'
      ? d.merchants.find((m) => m.id === target.id)
      : d.captains.find((c) => c.id === target.id);
  if (!account) return fail('الحساب غير موجود');
  const name = 'businessName' in account ? account.businessName : account.fullName;
  account.password = temporaryPassword;
  d.adminAudit.unshift({ id: uid('au'), kind: 'password_reset', targetRole: target.role, targetId: target.id, targetName: name, actor: ADMIN_ACTOR, at: now });
  return ok({ name, username: account.username });
}
